func (p *pwmPin) export() {
	writeFile(pwmExportPath(), []byte(p.pin))
}

// export writes pin to pwm unexport path
func (p *pwmPin) unexport() {
	writeFile(pwmUnExportPath(), []byte(p.pin))
}

// close disables and unexports pin
func (p *pwmPin) close() {
	p.enable("0")
	p.unexport()
}

